import base64
import hashlib
import io
import json
import os
from pathlib import Path
import subprocess
import tarfile
raw=base64.b64decode('')
assert hashlib.sha256(raw).hexdigest()=='50a272683634c26d4593a60fd4ac88e2de4215dc54c0d938b63a2bd3416c8518'
root=Path('/datasets/nuscenes-full/hugsim/iter137_controller_20261009')
root.mkdir(exist_ok=False)
packet=root/'packet'
packet.mkdir()
with tarfile.open(fileobj=io.BytesIO(raw)) as archive:
 for member in archive.getmembers():
  p=Path(member.name)
  assert not p.is_absolute() and '..' not in p.parts and (member.isfile() or member.isdir())
 archive.extractall(packet)
files={str(p.relative_to(packet)):hashlib.sha256(p.read_bytes()).hexdigest() for p in packet.rglob('*') if p.is_file()}
(root/'deployment.json').write_text(json.dumps(dict(source_commit='3bbf160bc6be02b405d81d80ad2347a0167f9c73',packet_sha256='50a272683634c26d4593a60fd4ac88e2de4215dc54c0d938b63a2bd3416c8518',files=files),indent=2))
python='/opt/sentinel-stack/HUGSIM/.pixi/envs/default/bin/python'
work=packet/'experiments/iter137_controller_execution_contract'
env={**os.environ,'OPENBLAS_NUM_THREADS':'1','OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1'}
r=subprocess.run([python,str(work/'validate_contract.py')],capture_output=True,text=True,env=env,timeout=60)
(root/'source_parity.stdout').write_text(r.stdout)
(root/'source_parity.stderr').write_text(r.stderr)
print(json.dumps(dict(source_commit='3bbf160bc6be02b405d81d80ad2347a0167f9c73',packet_sha256='50a272683634c26d4593a60fd4ac88e2de4215dc54c0d938b63a2bd3416c8518',files=files,parity_returncode=r.returncode,parity_stdout=r.stdout,parity_stderr=r.stderr),indent=2))
assert r.returncode==0
